#set isochrones


#Convert 7 AM local time to UTC time for every time zone in the US, using the with_tz function

converted_times&lt;-list()

for (year_loop in year_list){


  #Create list for each year that converts the time zones
  converted_times[[year_loop]] &lt;- tibble(
    timezone = timezones
  ) %&gt;%
    mutate(
      local_time = map2(
        reference_date[[year_loop]], timezone,
        ~ ymd_hms(paste(.x, "07:00:00"), tz = .y)
      ),
      utc_time = map(local_time, ~ with_tz(.x, "UTC"))
    ) %&gt;%
    unnest(c(local_time, utc_time))
}

  #Create isochrone objects for transplant centersusing the mapboxapi package if results not already cached
  for (organ_loop in organ_list){


    all_center_path&lt;-paste0("cache/Transplant_center_all_60min_buffer_",organ_loop, ".RDS")
    if (file.exists(all_center_path)) {
      Transplant_center_all_buffer[[organ_loop]][["60min"]] &lt;- 
        readRDS(all_center_path)
    }else {

      Transplant_center_all_buffer[[organ_loop]][["60min"]]&lt;-
        set_60_min_isochrone_at_7AM(Transplant_centers_all_sf[[organ_loop]], "2017")
      saveRDS(Transplant_center_all_buffer[[organ_loop]][["60min"]],
              all_center_path)
    } 

    for (year_loop in year_list){



    active_center_path&lt;-paste0("cache/Transplant_centers_active_60min_buffer_",organ_loop, "_", year_loop,".RDS")
    if (file.exists(active_center_path)) {
      Transplant_centers_active_buffer[[organ_loop]][["60min"]][[year_loop]] &lt;- 
        readRDS(active_center_path)
    }else {

    Transplant_centers_active_buffer[[organ_loop]][["60min"]][[year_loop]]&lt;-
      set_60_min_isochrone_at_7AM(Transplant_centers_active_SF[[organ_loop]][[year_loop]], year_loop)
    saveRDS(Transplant_centers_active_buffer[[organ_loop]][["60min"]][[year_loop]],
            active_center_path)
    }

    HIV_center_path&lt;-paste0("cache/Transplant_centers_HIV_60min_buffer_",organ_loop, "_", year_loop,".RDS")
    if (file.exists(HIV_center_path)) {
      Transplant_centers_HIV_buffer[[organ_loop]][["60min"]][[year_loop]]&lt;-
        readRDS(HIV_center_path)
    } else {
      Transplant_centers_HIV_buffer[[organ_loop]][["60min"]][[year_loop]]&lt;-
        set_60_min_isochrone_at_7AM(Transplant_centers_HIV_sf[[organ_loop]][[year_loop]], year_loop)
      saveRDS(Transplant_centers_HIV_buffer[[organ_loop]][["60min"]][[year_loop]],
              HIV_center_path)
    }


    HOPE_center_path&lt;-paste0("cache/Transplant_centers_HOPE_60min_buffer_",organ_loop, "_", year_loop,".RDS")
    if (file.exists(HOPE_center_path)) {
      Transplant_centers_HOPE_buffer[[organ_loop]][["60min"]][[year_loop]]&lt;-
        readRDS(HOPE_center_path)
    } else {
      Transplant_centers_HOPE_buffer[[organ_loop]][["60min"]][[year_loop]]&lt;-
        set_60_min_isochrone_at_7AM(Transplant_centers_HOPE_sf[[organ_loop]][[year_loop]], year_loop)
      saveRDS(Transplant_centers_HOPE_buffer[[organ_loop]][["60min"]][[year_loop]],
              HOPE_center_path)
    }
  }
}

Create diagram to explain calculations
This chunk uses {DiagrammeR} to create a schematic of how the geographic access analysis is assembled. The figure is organized from top to bottom:

Data sources appear in gray ovals at the top.
Derived analytic layers appear in blue boxes in the middle.
The geographic access model appears in tan.
The final output appears in green.

The workflow combines six main inputs:

SRTR transplant registry data to classify transplant centers as active, HIV transplant, or HOPE centers.
HRSA transplant center data to locate transplant centers.
US Census TIGER geographic data to construct fixed-distance buffers around centers.
Mapbox routing API to generate travel-time isochrones.
CDC HIV surveillance data to provide county-level HIV burden.
US Census population (ACS) to support tract-level allocation of HIV burden.

These inputs are transformed into the main analytic layers shown in the figure:

Transplant center classification
Transplant center locations
Distance buffers at 50, 100, and 200 miles
Travel-time isochrones at 60 minutes
Tract HIV burden estimates

Those layers are then combined in the geographic access model, which intersects access zones with tract-level HIV population estimates to quantify the population with geographic access to HIV transplant centers.

Notes on the DiagrammeR / Graphviz code
A few implementation details in the Graphviz code are worth noting:

rankdir = TB lays the diagram out from top to bottom.
ranksep and nodesep control the amount of vertical and horizontal spacing.
Separate node blocks are used to assign distinct styles to source nodes, derived nodes, the model, and the result.
HTML-like labels inside TABLE tags are used so multiline text and bullet-style formatting render cleanly inside boxes.
Invisible edges such as tiger -&gt; dist [style=invis] are included only to stabilize alignment; they do not represent substantive analytic relationships.
The chunk exports both an SVG and a high-resolution PNG version of the figure for reuse in slides or manuscripts.



